"package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("Error opening DB:", err)
		os.Exit(1)
	}
	defer db.Close()

	rows, err := db.Query("SELECT display_name, duration_seconds, cue_in, cue_out FROM media_library LIMIT 30")
	if err != nil {
		fmt.Println("Error querying DB:", err)
		os.Exit(1)
	}
	defer rows.Close()

	fmt.Println("Display Name | Duration | Cue In | Cue Out")
	fmt.Println("--------------------------------------------")
	for rows.Next() {
		var name string
		var duration int
		var cueIn, cueOut float64
		if err := rows.Scan(&name, &duration, &cueIn, &cueOut); err == nil {
			fmt.Printf("%s | %d | %.2f | %.2f\n", name, duration, cueIn, cueOut)
		}
	}
}
"

"package main

import (
	"database/sql"
	"fmt"
	"os"

	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("Error opening DB:", err)
		os.Exit(1)
	}
	defer db.Close()

	names := []string{
		"Voice Of America's Sons",
		"Brothers in Arms",
		"private investigations",
		"Thriller",
		"Shout",
		"Rock Your Baby",
		"I'm Gonna Get You (Original Remix Version)",
		"Da Funk",
		"Sweet Dreams",
		"Think About The Way",
	}

	fmt.Println("Display Name | Duration | Cue In | Cue Out")
	fmt.Println("--------------------------------------------")
	for _, name := range names {
		var dName string
		var duration int
		var cueIn, cueOut float64
		err := db.QueryRow("SELECT display_name, duration_seconds, cue_in, cue_out FROM media_library WHERE display_name LIKE ?", "%"+name+"%").Scan(&dName, &duration, &cueIn, &cueOut)
		if err == nil {
			fmt.Printf("%s | %d | %.2f | %.2f\n", dName, duration, cueIn, cueOut)
		} else {
			fmt.Printf("Not found: %s (%v)\n", name, err)
		}
	}
}
"

