+// isBlockPastScheduleEnd checks if the given blockTime is past the business hours of the schedule
+func isBlockPastScheduleEnd(blockTime time.Time, schedule *BasicSchedule, targetPlayTime time.Time) bool {
+	if schedule == nil {
+		return false
+	}
+	var eh, em, es int
+	_, _ = fmt.Sscanf(schedule.EndTime, "%d:%d:%d", &eh, &em, &es)
+	endSeconds := eh*3600 + em*60 + es
+
+	blockSeconds := blockTime.Hour()*3600 + blockTime.Minute()*60 + blockTime.Second()
+
+	var sh, sm, ss int
+	_, _ = fmt.Sscanf(schedule.StartTime, "%d:%d:%d", &sh, &sm, &ss)
+	startSeconds := sh*3600 + sm*60 + ss
+
+	if startSeconds <= endSeconds {
+		return blockSeconds > endSeconds || blockTime.Day() != targetPlayTime.Day()
+	} else {
+		// Overnight: e.g. start 22:00, end 06:00
+		return blockSeconds > endSeconds && blockSeconds < startSeconds
+	}
+}
