func main() {
	db, err := sql.Open("sqlite", "local_cache.db")
	if err != nil {
		fmt.Println("Error opening DB:", err)
		os.Exit(1)
	}
	defer db.Close()

	// Query store_info
	var gridID string
	err = db.QueryRow("SELECT audio_grid_id FROM store_info").Scan(&gridID)
	if err != nil {
		fmt.Println("Error querying store_info:", err)
	} else {
		fmt.Println("Active Grid ID:", gridID)
	}

	// Query weekly_master_grids
	rows, err := db.Query("SELECT * FROM weekly_master_grids")
	if err == nil {
		defer rows.Close()
		cols, _ := rows.Columns()
		fmt.Println("weekly_master_grids columns:", cols)
		for rows.Next() {
			// just print a placeholder or count
		}
	}

	// Let's print active schedules and their start/end times
	rows2, err2 := db.Query("SELECT id, name, start_time, end_time FROM basic_schedules")
	if err2 == nil {
		defer rows2.Close()
		fmt.Println("\nSchedules:")
		for rows2.Next() {
			var id, name, start, end string
			if err := rows2.Scan(&id, &name, &start, &end); err == nil {
				fmt.Printf("ID: %s | Name: %s | Start: %s | End: %s\n", id, name, start, end)
			}
		}
	}

	// Let's print block configs
	rows3, err3 := db.Query("SELECT id, name, interval_minutes, block_limit_seconds FROM commercial_block_configs")
	if err3 == nil {
		defer rows3.Close()
		fmt.Println("\nBlock Configs:")
		for rows3.Next() {
			var id, name string
			var interval, limit int
			if err := rows3.Scan(&id, &name, &interval, &limit); err == nil {
				fmt.Printf("ID: %s | Name: %s | Interval: %dm | Limit: %ds\n", id, name, interval, limit)
			}
		}
	}
}
"

