"// CleanOldHistory prunes play history older than 48 hours to keep the database light.
func CleanOldHistory() {
	if DB == nil {
		return
	}
	cutoff := time.Now().Add(-48 * time.Hour).Format("2006-01-02 15:04:05")
	_, err := DB.Exec("DELETE FROM play_history WHERE played_at < $1", cutoff)
	if err != nil {
		LogLocal("ERROR", "Failed to clean old play history: %v", err)
	}
}

// ResetQueuedSlots sets any planned slots with status 'QUEUED' back to 'PENDING'
// to ensure they are re-queued if the player was restarted before playing them.
func ResetQueuedSlots() {
	if DB == nil {
		return
	}
	_, err := DB.Exec("UPDATE planned_commercial_slots SET status = 'PENDING' WHERE status = 'QUEUED'")
	if err != nil {
		LogLocal("ERROR", "Failed to reset queued slots to pending: %v", err)
	} else {
		LogLocal("INFO", "Reset any previously queued commercial slots to pending.")
	}
}"

