"// formatAnnotatedURI creates the annotated protocol string for Liquidsoap
func formatAnnotatedURI(item PlayItem) string {
	// Standard Liquidsoap protocol format: annotate:key1="val1",key2="val2":uri
	// Path must point to the local decrypting server on port 5005
	sanitizePlayItemCues(&item)

	escapedPath := strings.ReplaceAll(item.LocalPath, `\`, `/`)
	uri := fmt.Sprintf("http://localhost:5005/play?path=%s", url.QueryEscape(escapedPath))

	amp := item.Amplify
	if amp <= 0.0 {
		amp = 1.0
	}

	var annotations []string
	annotations = append(annotations, fmt.Sprintf(`id="%s"`, item.ID))
	annotations = append(annotations, fmt.Sprintf(`type="%s"`, item.Type))
	annotations = append(annotations, fmt.Sprintf(`title="%s"`, item.DisplayName))
	annotations = append(annotations, fmt.Sprintf(`artist="%s"`, item.Artist))
	annotations = append(annotations, fmt.Sprintf(`duration="%d"`, item.DurationSeconds))
	annotations = append(annotations, fmt.Sprintf(`liq_amplify="%.2f"`, amp))

	// Only include cue_in if it is custom (> 0.0)
	if item.CueIn > 0.0 {
		annotations = append(annotations, fmt.Sprintf(`liq_cue_in="%.2f"`, item.CueIn))
	}

	// Only include cue_out if it is custom (< DurationSeconds)
	if item.CueOut > 0.0 && item.CueOut < float64(item.DurationSeconds) {
		annotations = append(annotations, fmt.Sprintf(`liq_cue_out="%.2f"`, item.CueOut))
	}

	annotationStr := strings.Join(annotations, ",")
	return fmt.Sprintf("annotate:%s:%s", annotationStr, uri)
}"

