func RotateLogFile(filePath string, maxSize int64) {
	info, err := os.Stat(filePath)
	if err != nil {
		return // File does not exist or cannot be accessed
	}
	if info.Size() < maxSize {
		return
	}

	// Shift old backups: .3 -> deleted, .2 -> .3, .1 -> .2, original -> .1
	for i := 3; i >= 1; i-- {
		oldPath := fmt.Sprintf("%s.%d", filePath, i)
		if i == 3 {
			_ = os.Remove(oldPath)
		} else {
			newPath := fmt.Sprintf("%s.%d", filePath, i+1)
			if _, errStat := os.Stat(oldPath); errStat == nil {
				_ = os.Rename(oldPath, newPath)
			}
		}
	}
	_ = os.Rename(filePath, filePath+".1")
}

