"package main

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	db, err := sql.Open("sqlite3", "local_cache.db")
	if err != nil {
		log.Fatalf("failed to open sqlite db: %v", err)
	}
	defer db.Close()

	rows, err := db.Query("SELECT id, file_name, display_name, cue_in, cue_out, is_downloaded FROM media_library WHERE file_name LIKE '%Lady%' OR display_name LIKE '%Lady%'")
	if err != nil {
		log.Fatalf("query failed: %v", err)
	}
	defer rows.Close()

	for rows.Next() {
		var id, fileName, displayName string
		var cueIn, cueOut float64
		var isDownloaded int
		if err := rows.Scan(&id, &fileName, &displayName, &cueIn, &cueOut, &isDownloaded); err != nil {
			log.Fatalf("scan failed: %v", err)
		}
		fmt.Printf("Local DB - ID: %s, File: %s, Display: %s, CueIn: %f, CueOut: %f, Downloaded: %d\n", id, fileName, displayName, cueIn, cueOut, isDownloaded)
	}
}
"

